-- Migration 486: AA-1142 (S292, the P2 features of the Ecosystem status page) — the availability objective, its error
-- budget window, the budget-left warn line and the burn rate alerts, the certificate expiry limits of the external checks, the incident timeline
-- lookback and the size of the per-agency rankings, as settings.
--
-- Why. The S285 review of the status page (root docs/audits/2026-11-19-S285-session/ops-overview-v2-review.md, ideas
-- 9-12) picked SLO + error budget burn, the incident record, external synthetic checks and a per-agency drill-down as
-- P2. Every objective, window, factor and limit they use is a setting (tech lead S279), never a code literal. The
-- smallest number of requests a window needs before it is judged is the CIS 475 key cis.ops.status_min_requests and
-- the freshness of the external results the CIS 475 key cis.ops.status_stale_factor (both reused, not repeated).
--
-- What:
--   1. Eleven rows in shared.setting_definition (seed block below, read by scripts/settings/gen_compiled_defaults.py into
--      shared/settings/compiled_defaults.json in this PR), app cis, area "ops", scope platform, impact low,
--      maker-checker, no evidence, no env override, enforced (shared/ops_status_thresholds.py names every key, the
--      settings-lint reader check). Defaults are the S285 review and SRE Workbook values:
--        cis.ops.status_slo_target_pct             numeric % 90-99.99, default 99.5 (availability objective per app)
--        cis.ops.status_slo_window_days            int days 7-90, default 30 (the error budget window)
--        cis.ops.status_slo_budget_warn_pct        int % 1-90, default 25 (budget left under it: amber)
--        cis.ops.status_burn_fast_window_min       int minutes 5-240, default 60
--        cis.ops.status_burn_fast_factor           numeric x 1-100, default 14.4 (SEV2 above it)
--        cis.ops.status_burn_slow_window_hours     int hours 1-72, default 6
--        cis.ops.status_burn_slow_factor           numeric x 1-100, default 6 (SEV3 above it)
--        cis.ops.status_cert_warn_days             int days 1-90, default 21 (external check certificate: warn)
--        cis.ops.status_cert_crit_days             int days 1-60, default 7 (critical, SEV2)
--        cis.ops.status_incident_lookback_min      int minutes 0-1440, default 60 (timeline before the declaration)
--        cis.ops.status_tenant_top_n               int agencies 3-50, default 10 (rows per per-agency ranking)
--      Each seed row carries its plain label and its EN + VI operator guide (CIS 416 rule).
--   2. Register 486.
--
-- Behaviour on apply. None for running code: no value row is seeded and the code on main reads none of the keys. After
-- the code PR the page reads the defaults until an administrator changes them.
--
-- Class: CONTRACT (root ADR 0017 decision 3; no migrate directive line): config rows INSERTed into an existing table.
-- MIG-4: a migration-only PR together with CIS 485 (expand, the three tables), applied on Dev by Infra Migration Apply
-- when the job tables are idle (ADR 0017a), then the code PR (readiness requires 485 and 486). DM-6.1: no personal
-- data. DM-7.1: no new table.
--
-- Number. Owner main max (484, AA-1169) + 2, after 485 of the same CIS migration batch (485-486). If the owner main max + 1
-- differs at merge, renumber (git grep '486_' and '486' here, in tests/integration/test_aa1142_migration_485_486.py,
-- compiled_defaults.json's _generated line, api/core/readiness.py and docs/implementation-notes/AA-1142.md).
--
-- Locks. One INSERT ... ON CONFLICT of eleven rows (the definition guard trigger allows the file's role, cis_owner).
-- lock_timeout 5s. Re-runnable: ON CONFLICT DO NOTHING keeps a row an earlier run wrote.
--
-- Rollback (a new forward migration, after the code PR is reverted): DELETE the eleven keys' value rows first, then
-- the keys.

BEGIN;
SET LOCAL lock_timeout = '5s';

-- settings-seed:begin (scripts/settings/gen_compiled_defaults.py reads the JSON array of the dollar-quoted seed)
INSERT INTO shared.setting_definition
    (key, app, area, label, description, value_type, unit, min_value, max_value, allowed_values, default_value,
     scope_kind, impact, approval, evidence_required, env_override, cache_s, enforced, guide)
SELECT s.key, s.app, s.area, s.label, s.description, s.value_type, s.unit, s.min_value, s.max_value, s.allowed_values,
       s.default_value, s.scope_kind, s.impact, s.approval, s.evidence_required, s.env_override, s.cache_s, s.enforced,
       s.guide
  FROM jsonb_to_recordset($seed$
[
{"key": "cis.ops.status_slo_target_pct", "app": "cis", "area": "ops", "label": "Status page: availability objective per app (SLO, %)", "description": "On the Ecosystem status page (/admin/overview, api/services/ops_status/) each app's availability (share of requests without a server error, 5xx, over cis.ops.status_slo_window_days days; the partner CRM, whose requests are not measured, by its 5-minute health samples) is compared with this objective; the error budget is 100 % minus it, and the burn rates of cis.ops.status_burn_fast_factor and cis.ops.status_burn_slow_factor are multiples of it. S285 review default 99.5 %.", "value_type": "numeric", "unit": "%", "min_value": 90, "max_value": 99.99, "allowed_values": null, "default_value": 99.5, "scope_kind": "platform", "impact": "low", "approval": "maker_checker", "evidence_required": false, "env_override": null, "cache_s": 60, "enforced": true, "guide": {"en": {"what": "The share of requests each app should answer without a server error; the rest is the error budget.", "raise": "Fewer errors are allowed: the budget is smaller, burns faster and alerts sooner.", "lower": "More errors are allowed before the budget runs out or a burn alert fires.", "when": "Keep 99.5 % on Dev; agree the prod objective with the business owner before the first tenant.", "example": "With the default 99.5 %, an app serving 100,000 requests in the window may answer 500 of them with a server error."}, "vi": {"what": "Tỷ lệ yêu cầu mỗi app phải trả lời không lỗi máy chủ; phần còn lại là ngân sách lỗi.", "raise": "Cho phép ít lỗi hơn: ngân sách nhỏ hơn, cháy nhanh hơn và cảnh báo sớm hơn.", "lower": "Cho phép nhiều lỗi hơn trước khi hết ngân sách hoặc có cảnh báo tốc độ cháy.", "when": "Giữ 99,5 % trên Dev; chốt mục tiêu prod với chủ doanh nghiệp trước tenant đầu tiên.", "example": "Với mặc định 99,5 %, app phục vụ 100.000 yêu cầu trong cửa sổ được phép trả lỗi máy chủ cho 500 yêu cầu."}}},
{"key": "cis.ops.status_slo_window_days", "app": "cis", "area": "ops", "label": "Status page: error budget window (days)", "description": "On the Ecosystem status page (/admin/overview, api/services/ops_status/) the availability and the error budget left of each app are counted over this many days up to now (a rolling window). Default 30.", "value_type": "int", "unit": "days", "min_value": 7, "max_value": 90, "allowed_values": null, "default_value": 30, "scope_kind": "platform", "impact": "low", "approval": "maker_checker", "evidence_required": false, "env_override": null, "cache_s": 60, "enforced": true, "guide": {"en": {"what": "How many past days the availability objective and its error budget cover.", "raise": "A longer memory: one bad day weighs less, and the budget refills slower after it.", "lower": "A shorter memory: the budget refills sooner, and one bad day weighs more.", "when": "Keep 30 days, the usual monthly objective.", "example": "With the default 30, on 25/11 the budget counts the requests from 26/10 to now."}, "vi": {"what": "Ngân sách lỗi và mục tiêu khả dụng tính trên bao nhiêu ngày gần nhất.", "raise": "Nhớ lâu hơn: một ngày xấu nhẹ hơn, ngân sách hồi chậm hơn sau đó.", "lower": "Nhớ ngắn hơn: ngân sách hồi sớm hơn, một ngày xấu nặng hơn.", "when": "Giữ 30 ngày, mục tiêu theo tháng thông dụng.", "example": "Với mặc định 30, ngày 25/11 ngân sách tính các yêu cầu từ 26/10 tới nay."}}},
{"key": "cis.ops.status_slo_budget_warn_pct", "app": "cis", "area": "ops", "label": "Status page: error budget left warn line (%)", "description": "On the Ecosystem status page (/admin/overview, api/services/ops_status/) the error budget left of an app (over cis.ops.status_slo_window_days days, against cis.ops.status_slo_target_pct) is coloured amber when this share of the budget or less is left, and red when the budget is spent (0 % or less). Default 25.", "value_type": "int", "unit": "%", "min_value": 1, "max_value": 90, "allowed_values": null, "default_value": 25, "scope_kind": "platform", "impact": "low", "approval": "maker_checker", "evidence_required": false, "env_override": null, "cache_s": 60, "enforced": true, "guide": {"en": {"what": "How much of an app's error budget may be left before its budget bar turns amber.", "raise": "Earlier amber bars: more time to slow down risky changes, more amber on a noisy Dev.", "lower": "Amber only when the budget is nearly spent, less time to react.", "when": "Keep 25 %; raise it before a busy release period.", "example": "With the default 25, an app with 20 % of its budget left shows an amber bar."}, "vi": {"what": "Ngân sách lỗi của app còn bao nhiêu phần trăm thì thanh ngân sách chuyển vàng.", "raise": "Thanh vàng sớm hơn: thêm thời gian để chậm lại các thay đổi rủi ro, nhiều vàng hơn trên Dev nhiễu.", "lower": "Chỉ vàng khi ngân sách gần hết, ít thời gian phản ứng hơn.", "when": "Giữ 25 %; tăng trước một đợt phát hành dày.", "example": "Với mặc định 25, app còn 20 % ngân sách hiện thanh màu vàng."}}},
{"key": "cis.ops.status_burn_fast_window_min", "app": "cis", "area": "ops", "label": "Status page: fast burn window (minutes)", "description": "On the Ecosystem status page (/admin/overview, api/services/ops_status/) the fast burn rate of each app is its share of server errors over this many minutes up to now divided by the error budget (100 % minus cis.ops.status_slo_target_pct); above cis.ops.status_burn_fast_factor it is a SEV2 item. SRE Workbook default 60.", "value_type": "int", "unit": "minutes", "min_value": 5, "max_value": 240, "allowed_values": null, "default_value": 60, "scope_kind": "platform", "impact": "low", "approval": "maker_checker", "evidence_required": false, "env_override": null, "cache_s": 60, "enforced": true, "guide": {"en": {"what": "How many recent minutes the fast burn alert looks at.", "raise": "Steadier: a short burst alone does not fire it, a real outage fires a little later.", "lower": "Faster: a short burst of errors can fire it.", "when": "Keep one hour with the factor 14.4 (2 % of a 30-day budget in one hour).", "example": "With the default 60, at 10:30 the fast burn counts the requests from 09:30."}, "vi": {"what": "Cảnh báo cháy nhanh xem bao nhiêu phút gần nhất.", "raise": "Ổn định hơn: một đợt lỗi ngắn không đủ báo, sự cố thật báo muộn hơn chút.", "lower": "Nhanh hơn: một đợt lỗi ngắn có thể gây báo.", "when": "Giữ một giờ với hệ số 14,4 (2 % ngân sách 30 ngày trong một giờ).", "example": "Với mặc định 60, lúc 10:30 tốc độ cháy nhanh tính các yêu cầu từ 09:30."}}},
{"key": "cis.ops.status_burn_fast_factor", "app": "cis", "area": "ops", "label": "Status page: fast burn alert factor", "description": "On the Ecosystem status page (/admin/overview, api/services/ops_status/) an app whose error share over cis.ops.status_burn_fast_window_min minutes is above this many times its error budget share is a SEV2 Needs-attention item (it would spend the whole budget in the window days divided by this factor). Requests under cis.ops.status_min_requests in the window are not judged. SRE Workbook default 14.4.", "value_type": "numeric", "unit": "x", "min_value": 1, "max_value": 100, "allowed_values": null, "default_value": 14.4, "scope_kind": "platform", "impact": "low", "approval": "maker_checker", "evidence_required": false, "env_override": null, "cache_s": 60, "enforced": true, "guide": {"en": {"what": "How many times faster than allowed an app may spend its error budget over the last hour before the page raises an alert.", "raise": "Only a severe outage raises the alert.", "lower": "Smaller bursts raise the alert, with more noise on Dev.", "when": "Keep 14.4 with a one-hour window and a 30-day budget.", "example": "With the default 14.4 and a 99.5 % objective, more than 7.2 % server errors in the last hour raise a SEV2 item."}, "vi": {"what": "App được tiêu ngân sách lỗi nhanh hơn mức cho phép bao nhiêu lần trong giờ qua trước khi trang báo động.", "raise": "Chỉ sự cố nặng mới báo.", "lower": "Đợt lỗi nhỏ hơn cũng báo, nhiễu hơn trên Dev.", "when": "Giữ 14,4 với cửa sổ một giờ và ngân sách 30 ngày.", "example": "Với mặc định 14,4 và mục tiêu 99,5 %, hơn 7,2 % lỗi máy chủ trong giờ qua tạo một mục SEV2."}}},
{"key": "cis.ops.status_burn_slow_window_hours", "app": "cis", "area": "ops", "label": "Status page: slow burn window (hours)", "description": "On the Ecosystem status page (/admin/overview, api/services/ops_status/) the slow burn rate of each app is its share of server errors over this many hours up to now divided by the error budget; above cis.ops.status_burn_slow_factor it is a SEV3 item. SRE Workbook default 6.", "value_type": "int", "unit": "hours", "min_value": 1, "max_value": 72, "allowed_values": null, "default_value": 6, "scope_kind": "platform", "impact": "low", "approval": "maker_checker", "evidence_required": false, "env_override": null, "cache_s": 60, "enforced": true, "guide": {"en": {"what": "How many recent hours the slow burn alert looks at.", "raise": "Catches a slower leak, but later.", "lower": "Reacts sooner, closer to the fast alert.", "when": "Keep 6 hours with the factor 6 (5 % of a 30-day budget in 6 hours).", "example": "With the default 6, at 14:00 the slow burn counts the requests from 08:00."}, "vi": {"what": "Cảnh báo cháy chậm xem bao nhiêu giờ gần nhất.", "raise": "Bắt được rò rỉ chậm hơn, nhưng muộn hơn.", "lower": "Phản ứng sớm hơn, gần với cảnh báo nhanh.", "when": "Giữ 6 giờ với hệ số 6 (5 % ngân sách 30 ngày trong 6 giờ).", "example": "Với mặc định 6, lúc 14:00 tốc độ cháy chậm tính các yêu cầu từ 08:00."}}},
{"key": "cis.ops.status_burn_slow_factor", "app": "cis", "area": "ops", "label": "Status page: slow burn alert factor", "description": "On the Ecosystem status page (/admin/overview, api/services/ops_status/) an app whose error share over cis.ops.status_burn_slow_window_hours hours is above this many times its error budget share is a SEV3 Needs-attention item. Requests under cis.ops.status_min_requests in the window are not judged. SRE Workbook default 6.", "value_type": "numeric", "unit": "x", "min_value": 1, "max_value": 100, "allowed_values": null, "default_value": 6, "scope_kind": "platform", "impact": "low", "approval": "maker_checker", "evidence_required": false, "env_override": null, "cache_s": 60, "enforced": true, "guide": {"en": {"what": "How many times faster than allowed an app may spend its error budget over the slow window before the page raises a ticket-level alert.", "raise": "Only a strong, lasting error rate raises it.", "lower": "A mild lasting error rate raises it.", "when": "Keep 6 with a 6-hour window and a 30-day budget.", "example": "With the default 6 and a 99.5 % objective, more than 3 % server errors over 6 hours raise a SEV3 item."}, "vi": {"what": "App được tiêu ngân sách lỗi nhanh hơn mức cho phép bao nhiêu lần trong cửa sổ chậm trước khi trang báo mức ticket.", "raise": "Chỉ tỷ lệ lỗi cao và kéo dài mới báo.", "lower": "Tỷ lệ lỗi nhẹ nhưng kéo dài cũng báo.", "when": "Giữ 6 với cửa sổ 6 giờ và ngân sách 30 ngày.", "example": "Với mặc định 6 và mục tiêu 99,5 %, hơn 3 % lỗi máy chủ trong 6 giờ tạo một mục SEV3."}}},
{"key": "cis.ops.status_cert_warn_days", "app": "cis", "area": "ops", "label": "Status page: certificate expiry warn (days left)", "description": "On the Ecosystem status page (/admin/overview, api/services/ops_status/) an external check whose TLS certificate ends in this many days or fewer is coloured warn on the external strip (root repo workflow External checks, every 15 minutes). Default 21.", "value_type": "int", "unit": "days", "min_value": 1, "max_value": 90, "allowed_values": null, "default_value": 21, "scope_kind": "platform", "impact": "low", "approval": "maker_checker", "evidence_required": false, "env_override": null, "cache_s": 60, "enforced": true, "guide": {"en": {"what": "How many days before a public certificate ends the external strip turns amber.", "raise": "Earlier warnings; managed certificates that renew by themselves may show amber for a while.", "lower": "Fewer amber rows, less time to act if a renewal fails.", "when": "Keep three weeks: managed certificates renew about a month before they end.", "example": "With the default 21, a certificate ending in 15 days shows amber."}, "vi": {"what": "Còn bao nhiêu ngày trước khi chứng chỉ công khai hết hạn thì dải external chuyển vàng.", "raise": "Cảnh báo sớm hơn; chứng chỉ tự gia hạn có thể hiện vàng một thời gian.", "lower": "Ít dòng vàng hơn, ít thời gian xử lý nếu gia hạn lỗi.", "when": "Giữ ba tuần: chứng chỉ được quản lý tự gia hạn khoảng một tháng trước khi hết.", "example": "Với mặc định 21, chứng chỉ hết hạn sau 15 ngày hiện màu vàng."}}},
{"key": "cis.ops.status_cert_crit_days", "app": "cis", "area": "ops", "label": "Status page: certificate expiry critical (days left)", "description": "On the Ecosystem status page (/admin/overview, api/services/ops_status/) an external check whose TLS certificate ends in this many days or fewer is critical and listed in Needs attention (SEV2). A value above the warn days is lowered to it. Default 7.", "value_type": "int", "unit": "days", "min_value": 1, "max_value": 60, "allowed_values": null, "default_value": 7, "scope_kind": "platform", "impact": "low", "approval": "maker_checker", "evidence_required": false, "env_override": null, "cache_s": 60, "enforced": true, "guide": {"en": {"what": "How many days before a public certificate ends the page asks for action.", "raise": "Earlier red rows and earlier action items.", "lower": "Red only when the certificate is about to end.", "when": "Keep a week: enough to fix a failed renewal.", "example": "With the default 7, a certificate ending in 5 days shows red and opens a SEV2 item."}, "vi": {"what": "Còn bao nhiêu ngày trước khi chứng chỉ công khai hết hạn thì trang yêu cầu xử lý.", "raise": "Dòng đỏ và việc cần làm xuất hiện sớm hơn.", "lower": "Chỉ đỏ khi chứng chỉ sắp hết hạn.", "when": "Giữ một tuần: đủ để sửa một lần gia hạn lỗi.", "example": "Với mặc định 7, chứng chỉ hết hạn sau 5 ngày hiện đỏ và mở một mục SEV2."}}},
{"key": "cis.ops.status_incident_lookback_min", "app": "cis", "area": "ops", "label": "Status page: incident timeline lookback (minutes)", "description": "On the Ecosystem status page (/admin/overview, api/services/ops_status/) the timeline of an incident starts this many minutes before it was declared (the deploys, alarms and service drops of its app that led up to it) and ends when it was resolved. Default 60.", "value_type": "int", "unit": "minutes", "min_value": 0, "max_value": 1440, "allowed_values": null, "default_value": 60, "scope_kind": "platform", "impact": "low", "approval": "maker_checker", "evidence_required": false, "env_override": null, "cache_s": 60, "enforced": true, "guide": {"en": {"what": "How far before an incident was declared its timeline starts.", "raise": "More of what happened before shows, with more unrelated events.", "lower": "A shorter timeline focused on the incident itself.", "when": "Keep an hour; raise it when incidents are declared long after the first alert.", "example": "With the default 60, an incident declared at 10:00 shows the events of its app from 09:00."}, "vi": {"what": "Dòng thời gian của sự cố bắt đầu bao lâu trước lúc khai báo.", "raise": "Thấy nhiều diễn biến trước hơn, kèm nhiều sự kiện không liên quan hơn.", "lower": "Dòng thời gian ngắn, tập trung vào chính sự cố.", "when": "Giữ một giờ; tăng khi sự cố thường được khai báo lâu sau cảnh báo đầu tiên.", "example": "Với mặc định 60, sự cố khai báo lúc 10:00 hiện các sự kiện của app từ 09:00."}}},
{"key": "cis.ops.status_tenant_top_n", "app": "cis", "area": "ops", "label": "Status page: agencies listed per ranking", "description": "On the Ecosystem status page (/admin/overview, api/services/ops_status/) the per-agency drill-down (GET /admin/overview/status/tenants) lists at most this many agencies in each ranking (AI spend, failed jobs, AI errors) over the page's time range. Default 10.", "value_type": "int", "unit": "agencies", "min_value": 3, "max_value": 50, "allowed_values": null, "default_value": 10, "scope_kind": "platform", "impact": "low", "approval": "maker_checker", "evidence_required": false, "env_override": null, "cache_s": 60, "enforced": true, "guide": {"en": {"what": "How many agencies each ranking of the per-agency drill-down shows.", "raise": "Longer lists, more scrolling.", "lower": "Only the top few agencies show.", "when": "Keep 10; raise it when many agencies are active.", "example": "With the default 10, the AI spend ranking shows the 10 agencies that spent the most in the range."}, "vi": {"what": "Mỗi bảng xếp hạng trong phần xem theo đại lý hiện tối đa bao nhiêu đại lý.", "raise": "Danh sách dài hơn, cuộn nhiều hơn.", "lower": "Chỉ hiện vài đại lý đứng đầu.", "when": "Giữ 10; tăng khi có nhiều đại lý hoạt động.", "example": "Với mặc định 10, bảng chi phí AI hiện 10 đại lý chi nhiều nhất trong khoảng thời gian."}}}
]
$seed$::jsonb) AS s (key text, app text, area text, label text, description text, value_type text, unit text,
                      min_value numeric, max_value numeric, allowed_values jsonb, default_value jsonb, scope_kind text,
                      impact text, approval text, evidence_required boolean, env_override text, cache_s integer,
                      enforced boolean, guide jsonb)
ON CONFLICT (key) DO NOTHING;
-- settings-seed:end

INSERT INTO shared.schema_versions (version, applied_at, description)
VALUES ('486', now(), 'AA-1142: Ecosystem status P2 settings (SLO, burn rate, certificates, incidents, agencies)')
ON CONFLICT (version) DO NOTHING;

COMMIT;
